begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name": "Martyn Canine Behavior \u2014 Private Lessons", "category": "Pet Services", "city": "Morada", "address": null, "phone": "(650) 898-9117", "website": "https://www.martyncaninebehavior.com/", "source_url": "https://www.martyncaninebehavior.com/contact/", "duplicate_key": "martyncaninebehavior.com", "areas": ["Manteca", "Tracy"], "tags": ["dog training", "puppy training"], "description": "Morada-based provider advertising private dog training in clients\u2019 homes and local communities, with Manteca and Tracy explicitly listed. This listing uses the published private-lessons phone, not the separate board-and-train contact. Confirm your address, dog needs, session location, program scope, quote and dates directly. No Lathrop or Mountain House coverage established.", "note": "First-party homepage and contact page checked November14,2026 with fresh HTTP200: identity, Morada base, private/home-community lessons, puppy/adult training, private-lessons phone6508989117 and individually named Manteca/Tracy coverage. No public visitor street office inferred; broad valley/county wording not extended to Lathrop/Mountain House. Board-and-train is described separately in Morada and is not tagged as ordinary pet boarding here. Credentials, experience, training results, methods/safety, quality, availability and prices not independently validated. Site copyright year is not check-date evidence. No provider photos, reviews or testimonials reused; no contact form submitted. Sources: https://www.martyncaninebehavior.com/ https://www.martyncaninebehavior.com/contact/"}]'::jsonb) loop
 if exists(select 1 from public.businesses where lower(name)=lower(r->>'name') or website ilike '%'||(r->>'duplicate_key')||'%' or (r->>'phone' is not null and right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10))) then raise exception 'Duplicate requires individual review: %',r->>'name'; end if;
 insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values(r->>'name',r->>'category',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,r->>'source_url',array['identity','public contact route','website','advertised services','explicit service cities','service limits'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
 select to_jsonb(b) into applied from public.businesses b where id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'Individually source-checked directory expansion; no seed publication',r->>'source_url');
end loop;end $curate$;
commit;
select b.id,b.name,b.city,b.verified_at,c.service_areas,c.service_tags,c.checked_at from public.businesses b join public.listing_checks c on c.business_id=b.id where b.website='https://www.martyncaninebehavior.com/';
